() => {
  const small = [];
  for (const el of document.querySelectorAll('body *')) {
    const cs = getComputedStyle(el);
    if (cs.display === 'none' || !el.textContent?.trim()) continue;
    const fs = parseFloat(cs.fontSize);
    if (fs < 16) small.push({ tag: el.tagName, cls: el.className?.toString().slice(0, 40), fs, text: el.textContent.trim().slice(0, 30) });
  }
  const main = document.querySelector('main'), aside = document.querySelector('aside');
  const mr = main.getBoundingClientRect(), ar = aside.getBoundingClientRect();
  return {
    small,
    toggle: !!document.querySelector('button[aria-controls="sheet"]'),
    main: [mr.x, mr.y, mr.width, mr.height], aside: [ar.x, ar.y, ar.width, ar.height],
    mainBeforeAside: main.nextElementSibling === aside,
    pins: document.querySelectorAll('.park-pin').length,
    pageScroll: document.documentElement.scrollHeight, inner: innerHeight,
    attribution: document.querySelector('.leaflet-control-attribution')?.getBoundingClientRect().toJSON(),
  };
}

