() => {
  const small = [];
  for (const el of document.querySelectorAll('body *')) {
    const cs = getComputedStyle(el);
    if (cs.display === 'none' || !el.textContent?.trim()) continue;
    const fs = parseFloat(cs.fontSize);
    if (fs < 16) small.push({ tag: el.tagName, cls: el.className?.toString().slice(0, 40), fs });
  }
  const main = document.querySelector('main'), aside = document.querySelector('aside');
  const btn = document.querySelector('button[aria-controls="sheet"]');
  const r = (e) => { const b = e.getBoundingClientRect(); return [Math.round(b.x), Math.round(b.y), Math.round(b.width), Math.round(b.height)]; };
  return {
    small, main: r(main), aside: r(aside), btn: btn && { text: btn.textContent.trim(), expanded: btn.getAttribute('aria-expanded'), rect: r(btn) },
    attribution: r(document.querySelector('.leaflet-control-attribution')),
    mainBeforeAside: main.nextElementSibling === aside, pins: document.querySelectorAll('.park-pin').length,
    scrollH: document.documentElement.scrollHeight, inner: innerHeight,
    pinYs: [...document.querySelectorAll('.park-pin')].map(p => Math.round(p.getBoundingClientRect().bottom)),
  };
}

